import UIKit

/// Captures new clipboard contents into `ClipboardStore` while the keyboard is visible.
///
/// iOS doesn't let keyboard extensions run in the background, so this only sees copies made
/// while the keyboard is on screen, plus the latest copy when the keyboard next appears.
final class PasteboardMonitor {
    /// Markers set by password managers (nspasteboard.org convention). Such items are never stored.
    private static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]

    var onChange: (() -> Void)?

    private let store: ClipboardStore
    private var timer: Timer?

    init(store: ClipboardStore) {
        self.store = store
    }

    deinit {
        timer?.invalidate()
    }

    func start() {
        stop()
        check()
        let timer = Timer(timeInterval: 1, repeats: true) { [weak self] _ in self?.check() }
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    func stop() {
        timer?.invalidate()
        timer = nil
    }

    /// Cheap when nothing changed: only `changeCount` is read, which never triggers paste UI.
    func check() {
        let pasteboard = UIPasteboard.general
        let count = pasteboard.changeCount
        guard count != store.lastSeenChangeCount else { return }
        store.lastSeenChangeCount = count

        guard pasteboard.hasStrings else { return }
        let types = Set(pasteboard.types)
        guard types.isDisjoint(with: Self.ignoredTypes) else { return }
        guard let text = pasteboard.string else { return }
        if store.add(text) { onChange?() }
    }
}
